def main():
    protected={}
    def read(p):protected[p.relative_to(GAME).as_posix()]=sha(p);return json.loads(p.read_text(encoding='utf-8-sig'))
    source=ROOT/'src/data/feats.js';raw=json.JSONDecoder().raw_decode(source.read_text(encoding='utf-8-sig').split('export const feats = ',1)[1])[0];by={x['id']:x for x in raw};protected[source.relative_to(GAME).as_posix()]=sha(source)
    reviewed=set(read(ROOT/'data/public/feat_playtests/manifest.json')['operationalIds'])
    routed={z['featId'] for n in ['CRAFTING_FEAT_INTERFACE','COMBAT_FEAT_SOURCE','SKILL_FEAT_SOURCE','MAGIC_CORE_FEAT_SOURCE','MAGIC_EXTENDED_FEAT_SOURCE','HERITAGE_MUTATION_FEAT_SOURCE'] for z in read(AUDIT/(n+'_PREPARATION.json'))['selectedFeats']}
    pending=read(AUDIT/'REMAINING_FEAT_CATALOG_PREPARATION.json');selected=[x for x in raw if x['id'] in QUESTIONS]
    assert len(selected)==31 and all(x['type']=='General' for x in selected)
